head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gIsurCd;
scwin.gImprRegDd;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.vScrenID = 'ULDSTF35113.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetProvider = function() {
    var url = frame.srcUrl;
    var arr = url.split("?");
    //alert("arr=>"+ arr[1]);
    return (arr.length >= 1 ? arr[1] : undefined);
};
scwin.fn_GetParentValue = function() {
    var pvd = scwin.fn_GetProvider();
    gPvd = pvd;
    //alert("pvd="+ pvd);
    if (pvd != null) {
        scwin.gIsurCd = pvd.split("=")[1];
        if ($c.ut.trim(scwin.gIsurCd).length == 5) {
            //alert(gIsurCd);
            $c.stf.setObjectValue(txb_isur_cd, scwin.gIsurCd);
            fn_Search();
        }
    }
};
scwin.fn_SetCode = function() {
    // 벌점부과유형  셋팅
    dts_ImpostTp.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=PNLT_IMPOST_TP_CD";
    dts_ImpostTp.Reset();

    // 벌점부과사유  셋팅
    dts_ImpostRsn.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=PNLT_IMPOST_RSN_CD";
    dts_ImpostRsn.Reset();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !벌점--;
클릭-- > function() {
    // 법인코드 자리수 체크 
    if ($c.stf.getObjectValue(txb_isur_cd).length != 5) {
        $c.win.alert("회사코드 5자리를 올바르게 입력하십시오.");
        txb_isur_cd.focus();
        return;
    }
    scwin.fn_Clear();

    // 1. 벌점부과현황 조회
    var url = "/PenaltyImposition.do?method=listPenaltyImpositionKonexPopupInfo" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //  데이타 조회
    dts_pnltsat_info.DataID = encodeURI(url);
    dts_pnltsat_info.reset();

    // 2. 벌점부과 상세내역
    //txb_TotalCnt.value = "총건수 : " ;	
    var url_list = "/PenaltyImposition.do?method=listPenaltyHistory&inputMessageId=PNLTINFO_INOUT" + "&outputMessageId=PNLTDTLLIST_OUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&LD_MKT_TP=6";

    //  데이타 조회
    dts_pnlt_history.DataID = encodeURI(url_list);
    dts_pnlt_history.reset();
};




// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gIsurCd = dts_pnlt_list.getCellData(eval(obj), "ISUR_CD");
};
scwin.fn_CheckValue = function() {
    var vIsurCd = $c.stf.getObjectValue(txb_isurcd);
    if (vIsurCd == "") {
        $c.win.alert("회사 선택후 벌점부과현황을 조회후에 입력처리가 가능합니다.");
        txb_isur_cd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_impost_dd) == "") {
        $c.win.alert("벌점부과일을 입력하십시오");
        edt_impost_dd.focus();
        return false;
    }
    var vToday = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(edt_impost_dd) < vToday) {
        $c.win.alert("벌점부과일에는 오늘 이후의 날짜만 입력할 수 있습니다");
        edt_impost_dd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_rsnoccr_dd) == "") {
        $c.win.alert("사유발생일을 입력하십시오");
        edt_rsnoccr_dd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_ImpostTp) == "") {
        $c.win.alert("벌점부과유형을 선택하십시오");
        cmb_ImpostTp.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_ImpostRsn) == "") {
        $c.win.alert("벌점부과사유를 선택하십시오");
        cmb_ImpostRsn.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_pnlt) == "") {
        $c.win.alert("벌점을 입력하십시오");
        txb_pnlt.focus();
        return false;
    }
    if (scwin.isNumJum($c.stf.getObjectValue(txb_pnlt)) == false) {
        $c.win.alert("숫자만 입력가능합니다.");
        txb_pnlt.focus();
        return false;
    }
    return true;
};
scwin.isNumJum = function(sVal) {
    if (('0' < sVal) || ('9' > sVal) || ('.' == sVal)) {
        return true;
    } else {
        return false;
    }
};



// 벌점 입력
scwin.fn_Insert = function() {
    if (scwin.fn_CheckValue() == false) {
        return;
    }
    dts_Pnlt_Input.insertRow();
    dts_Pnlt_Input.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_Pnlt_Input.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_isurcd));
    dts_Pnlt_Input.setCellData(1, "PNLT_IMPOST_DD", $c.stf.getObjectValue(edt_impost_dd));
    dts_Pnlt_Input.setCellData(1, "RSN_OCCR_DD", $c.stf.getObjectValue(edt_rsnoccr_dd));
    dts_Pnlt_Input.setCellData(1, "PNLT_IMPOST_TP_CD", $c.stf.getObjectValue(cmb_ImpostTp));
    dts_Pnlt_Input.setCellData(1, "PNLT_IMPOST_RSN_CD", $c.stf.getObjectValue(cmb_ImpostRsn));
    dts_Pnlt_Input.setCellData(1, "PNLT", $c.stf.getObjectValue(txb_pnlt));
    var vAnswer = confirm('벌점 입력처리 하시겠습니까?');
    if (vAnswer == true) {
        trs_Pnlt_Input.Action = "/PenaltyImposition.do?method=registerPenaltyImpositionKonex&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Pnlt_Input.KeyName = "toinb_dataid4";
        trs_Pnlt_Input.KeyValue = "JSP(I:pInput=dts_Pnlt_Input)";
        trs_Pnlt_Input.Post();
    }
};




// 입력항목 clear
scwin.fn_Clear = function() {
    $c.stf.setObjectValue(edt_impost_dd, "");
    $c.stf.setObjectValue(edt_rsnoccr_dd, "");
    $c.stf.setObjectValue(cmb_ImpostTp, "");
    $c.stf.setObjectValue(cmb_ImpostRsn, "");
    $c.stf.setObjectValue(txb_pnlt, "");
};
scwin.dts_ImpostTp_OnLoadCompleted = function(rowcount) {
    dts_ImpostTp.UseFilter = true;
    dts_ImpostTp.Filter();
    dts_ImpostTp.sort("VALUE", 0);
    //dts_ImpostTp.sort(); // W-Craft 주석처리 

};
scwin.dts_ImpostTp_OnFilter = function(row) {
    // 코스닥용 벌점부과유형 보여주기
    if (dts_ImpostTp.getCellData(row, "value") == '1' ||
        dts_ImpostTp.getCellData(row, "value") == '2' ||
        dts_ImpostTp.getCellData(row, "value") == '4' ||
        dts_ImpostTp.getCellData(row, "value") == '5' ||
        dts_ImpostTp.getCellData(row, "value") == '') {
        return true;
    } else {
        return false;
    }
};
scwin.dts_ImpostRsn_OnLoadCompleted = function(rowcount) {
    dts_ImpostRsn.UseFilter = true;
    dts_ImpostRsn.Filter();
    dts_ImpostRsn.sort("VALUE", 0);
    //dts_ImpostRsn.sort(); // W-Craft 주석처리 

};
scwin.dts_ImpostRsn_OnFilter = function(row) {
    // 코스닥용 벌점부과사유 보여주기
    if (dts_ImpostRsn.getCellData(row, "value") == '1' ||
        dts_ImpostRsn.getCellData(row, "value") == '2' ||
        dts_ImpostRsn.getCellData(row, "value") == '3' ||
        dts_ImpostRsn.getCellData(row, "value") == '4' ||
        dts_ImpostRsn.getCellData(row, "value") == '6' ||
        dts_ImpostRsn.getCellData(row, "value") == '7' ||
        dts_ImpostRsn.getCellData(row, "value") == '8' ||
        dts_ImpostRsn.getCellData(row, "value") == '') {
        return true;
    } else {
        return false;
    }
};
scwin.dts_pnltsat_info_OnLoadError = function() {
    $c.stf.alert_error(dts_pnltsat_info);
};
scwin.dts_pnlt_history_OnLoadError = function() {
    $c.win.alert(dts_pnlt_history);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_pnlt_history, "벌점부과상세내역 ", "", "8");
};
scwin.btn_Search_onclick = function() {
    fn_Search();
};
scwin.img_impost_dd_onclick = function() {
    popUpCalendar2(edt_impost_dd);
};
scwin.img_rsnoccr_dd_onclick = function() {
    popUpCalendar2(edt_rsnoccr_dd);
};
scwin.btn_Insert_onclick = function() {
    scwin.fn_Insert();
};
scwin.btn_Clear_onclick = function() {
    scwin.fn_Clear();
};
scwin.trs_Pnlt_Input_OnFail = function() {
    $c.win.alert('trs_Pnlt_Input.OnFail() :' + trs_Pnlt_Input.ErrorMsg);
};
scwin.trs_Pnlt_Input_OnSuccess = function() {
    $c.win.alert("성공적으로 입력처리 되었습니다.");

    // 화면 RELOAD
    fn_Search();
    // dataset 초기화
    dts_Pnlt_Input.removeAll();
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.dts_pnltsat_info_OnLoadCompleted = function(rowcount) {
    scwin.gIsurCd = dts_pnltsat_info.getCellData(1, "ISUR_CD");
};
scwin.gform_onload = function() {
    $c.stf.showObj(txb_isurcd, false); // 히든처리!
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();

    // 가우스헤더 셋팅
    dts_Pnlt_Input.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=PNLT_KONEX_REGISTER_INOUT";
    dts_Pnlt_Input.reset();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_GetParentValue();
};
